## 说明
`merge_intervals` 合并所有重叠或接触的闭区间，返回按起点排序的新列表。时间复杂度 O(n log n)，空间复杂度 O(n)。

## 测试代码
```python
import pytest

def merge_intervals(intervals):
    """合并闭区间，接触端点也合并"""
    if not intervals:
        return []
    intervals.sort(key=lambda x: x[0])
    merged = [list(intervals[0])]
    for start, end in intervals[1:]:
        if start <= merged[-1][1] + 1:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged


class TestMergeIntervals:
    def test_empty(self):
        assert merge_intervals([]) == []

    def test_single_interval(self):
        assert merge_intervals([[1, 3]]) == [[1, 3]]

    def test_no_overlap(self):
        assert merge_intervals([[1, 2], [4, 5]]) == [[1, 2], [4, 5]]

    def test_overlap(self):
        assert merge_intervals([[1, 3], [2, 6], [8, 10], [15, 18]]) == [[1, 6], [8, 10], [15, 18]]

    def test_touching_endpoints(self):
        assert merge_intervals([[1, 4], [5, 6]]) == [[1, 6]]

    def test_contained_interval(self):
        assert merge_intervals([[1, 10], [2, 5], [3, 7]]) == [[1, 10]]

    def test_unsorted_input(self):
        assert merge_intervals([[5, 7], [1, 3], [2, 4]]) == [[1, 4], [5, 7]]

    def test_identical_intervals(self):
        assert merge_intervals([[1, 3], [1, 3]]) == [[1, 3]]

    def test_adjacent_merge_chain(self):
        assert merge_intervals([[1, 2], [3, 4], [5, 6]]) == [[1, 6]]

    def test_negative_intervals(self):
        assert merge_intervals([[-5, -3], [-4, -1], [0, 2]]) == [[-5, 2]]

    def test_single_point_intervals(self):
        assert merge_intervals([[1, 1], [2, 2], [3, 3]]) == [[1, 3]]

    def test_mixed_overlap_and_touch(self):
        assert merge_intervals([[1, 4], [5, 8], [3, 6]]) == [[1, 8]]
```
